#include <bits/stdc++.h>
using namespace std;

int main() {
    string str;
    cin >> str;

    auto isVowel = [](char c) {
        return c == 'a' || c == 'e' || c == 'i' ||
               c == 'o' || c == 'u';
    };

    for (int i = 0; i < static_cast<int>(str.size()); ++i) {
        if (!isVowel(str[i]) && str[i] != 'n') {
            if (i + 1 == static_cast<int>(str.size()) || !isVowel(str[i + 1])) {
                cout << "NO";
                return 0;
            }
        }
    }

    cout << "YES";
    return 0;
}

